import {DEMO_CANDIDATE,answerQuestion,CHAT_SUGGESTIONS,createTicket,submitRequirement,reviewRequirement,nextAction,recommendations,saveActionPlan,updateActionPlan} from './workflow.js';
import {renderChat,requirementReview} from './workflow-pages.js';
import {audit,reminderEligibility} from './model.js';

export function createWorkflowUI(api){
  const {esc,icon,pill,fmt,modal,closeModal,toast,persist,render,go}=api;
  const state=()=>api.getState(),role=()=>api.getRole(),kit=()=>api.getKit();
  let conversationDraft='';
  function openChat(){modal('Tanya status demo',renderChat(kit(),role()));const log=document.querySelector('.chat-messages');if(log)log.scrollTop=log.scrollHeight;}
  function ask(question){const s=state(),key=role();const text=question.trim().slice(0,500);if(!text)return;const answer=answerQuestion(s,key,text);s.chats[key].push({actor:'user',text,time:s.now},{actor:'assistant',...answer,time:s.now});s.chats[key]=s.chats[key].slice(-30);persist();openChat();}
  function newTicket(prefill='',conversation=''){
    if(role()!=='student'){toast('Buka Demo Calon Mahasiswa untuk mengajukan bantuan.');return;}
    conversationDraft=conversation;
    const c=state().cases.find(c=>c.id===DEMO_CANDIDATE);
    modal('Ceritakan kendalamu.',`<form id="workflow-ticket-form"><label class="field">Kategori kendala<select name="category">${['Dokumen','Pembayaran','Akses sistem','Informasi pendaftaran','Kendala lainnya'].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="field">Ceritakan kendalamu<textarea name="text" required minlength="10" maxlength="2000">${esc(prefill)}</textarea></label>${conversation?`<details class="conversation-summary"><summary>Ringkasan percakapan yang akan disertakan</summary><p>${esc(conversation)}</p></details>`:''}<div class="help-box">Unit penerimaan simulasi · penanggung jawab ${esc(c.owner==='Belum ditugaskan'?'Koordinator layanan':c.owner)}. Jangan masukkan data pribadi nyata.</div><p class="error" role="alert"></p><div class="modal-actions"><button class="btn" type="submit">Buat Tiket Bantuan ${icon('arrow')}</button><button class="btn secondary" type="button" data-action="modal-close">Batal</button></div></form>`);
  }
  function handoff(){if(role()!=='student'){toast('Buka demo calon mahasiswa untuk membuat tiket.');return;}const messages=state().chats.student.slice(-8);const transcript=messages.map(m=>(m.actor==='user'?'Calon mahasiswa: ':'Tanya ADMIRA: ')+m.text).join('\n\n');const last=messages.filter(m=>m.actor==='user').at(-1)?.text;newTicket('Saya membutuhkan tindak lanjut petugas'+(last?' terkait: '+last:'. Mohon bantu saya memahami proses pendaftaran.'),transcript);}
  function ticketModal(id){
    const s=state(),t=s.tickets.find(t=>t.id===id);if(!t||role()==='public'||role()==='student'&&t.caseId!==DEMO_CANDIDATE)return;
    modal(`Tiket ${esc(t.id)}`,`<div class="ticket-assignment"><strong>${esc(t.unit)}</strong><span>Penanggung jawab: ${esc(t.owner)}</span><small>Target respons pertama simulasi: 4 jam layanan, Senin–Jumat 08.00–16.00 WIB.</small></div><div class="message"><strong>${esc(t.category)} · ${pill(t.status)}</strong><p>${esc(t.text)}</p><small>${fmt(t.created)}</small></div>${t.conversation?`<details class="conversation-summary"><summary>Ringkasan Tanya ADMIRA</summary><p>${esc(t.conversation)}</p></details>`:''}${t.messages.map(m=>`<div class="message response"><strong>${esc(m.actor)}</strong><p>${esc(m.text)}</p><small>${fmt(m.time)}</small></div>`).join('')}<form id="ticket-reply-form" data-id="${t.id}"><label class="field">${role()==='staff'?'Respons / ringkasan penyelesaian':'Tambahkan informasi'}<textarea name="text" required minlength="5" maxlength="2000"></textarea></label>${role()==='staff'?`<label class="field">Petugas penanggung jawab<select name="owner">${['Alya Rahma','Bima Prasetyo','Koordinator layanan'].map(n=>`<option ${n===t.owner?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Status tiket<select name="status">${['Baru','Ditangani','Menunggu calon mahasiswa','Menunggu unit lain','Selesai','Dibuka kembali'].map(v=>`<option ${v===t.status?'selected':''}>${v}</option>`).join('')}</select></label>`:''}<p class="error" role="alert"></p><div class="modal-actions"><button class="btn" type="submit">Simpan respons</button>${role()==='student'&&t.status==='Selesai'?`<button type="button" class="btn secondary" data-reopen="${t.id}">Minta dibuka kembali</button>`:''}</div></form><p class="login-note">Tiket selesai tidak otomatis menyelesaikan daftar ulang.</p>`);
  }
  function caseModal(id){
    if(role()!=='staff')return;const s=state(),c=s.cases.find(c=>c.id===id);if(!c)return;
    const reason=reminderEligibility(s,c),tickets=s.tickets.filter(t=>t.caseId===id);
    modal(esc(c.name),`<div class="case-summary"><span class="label">${esc(c.id)} · ${esc(c.prodi)} · ${esc(c.route||'Jalur belum tersedia')}</span><p>Status sumber: <strong>${esc(c.source)}</strong><br>Tenggat simulasi: ${fmt(c.deadline)}</p>${pill(c.status)}</div><div class="two-col section-gap"><div>${requirementReview(kit(),c)}${c.stage===3&&c.status==='Menunggu verifikasi'?`<section class="panel"><h3>Verifikasi aktivasi simulasi</h3><label class="field">Catatan<textarea id="review-reason"></textarea></label><p id="review-error" class="error" role="alert"></p><button class="btn" data-verify="${id}">Verifikasi selesai</button></section>`:''}<section class="case-tickets section-gap"><h3>Tiket bantuan terkait</h3>${tickets.length?tickets.map(t=>`<div class="message"><strong>${esc(t.id)} · ${esc(t.category)}</strong><p>${esc(t.text)}</p><small>${esc(t.owner)}</small><button class="text-btn" data-ticket="${t.id}">Buka tiket ${icon('arrow')}</button></div>`).join(''):'<p>Belum ada kendala dilaporkan.</p>'}</section></div><aside><form id="case-form" data-id="${id}"><label class="field">Penanggung jawab<select name="owner">${['Belum ditugaskan','Alya Rahma','Bima Prasetyo'].map(n=>`<option ${n===c.owner?'selected':''}>${n}</option>`).join('')}</select></label><button class="btn secondary" type="submit">Simpan penugasan</button></form><form id="followup-note-form" data-id="${id}" class="section-gap"><label class="field">Catatan tindak lanjut<textarea name="note" minlength="10" required maxlength="1500" placeholder="Apa yang ditinjau dan langkah berikutnya?"></textarea></label><p class="error" role="alert"></p><button class="btn secondary" type="submit">Catat tindak lanjut</button></form><div class="help-box"><h3>Pengingat kewajiban</h3><p>${esc(reason||'Tugas memenuhi syarat pengingat simulasi.')}</p><button class="text-btn" data-remind="${id}">Simulasikan pengingat ${icon('arrow')}</button></div><button class="text-btn section-gap" data-deadline="${id}">Ubah tenggat simulasi ${icon('calendar')}</button><h3 class="section-gap">Kronologi</h3><div class="case-history">${s.audit.filter(a=>a.entity===id).slice(0,8).map(a=>`<div><strong>${esc(a.action)}</strong><p>${esc(a.after||'')}</p><small>${fmt(a.time,false)} · ${esc(a.actor)}</small></div>`).join('')||'<p>Belum ada aktivitas baru.</p>'}</div></aside></div>`,true);
  }
  function recommendationModal(id){if(role()!=='staff')return;const r=recommendations(state(),api.getFilters()).find(r=>r.id===id);if(!r)return;const defaultDate=new Date(new Date(state().now).getTime()+7*86400000).toISOString().slice(0,10);modal('Susun rencana tindakan',`<h3>${esc(r.title)}</h3><div class="message"><p>${esc(r.finding)}</p><small>${esc(r.evidence)}</small></div><form id="action-plan-form" data-id="${r.id}"><label class="field">Usulan tindakan<textarea name="proposal" required minlength="10" maxlength="2000">${esc(r.proposal)}</textarea></label><label class="field">Penanggung jawab<select name="owner"><option>Alya Rahma</option><option>Bima Prasetyo</option></select></label><label class="field">Waktu evaluasi simulasi<input type="date" name="reviewDate" required value="${defaultDate}"></label><label class="field">Indikator evaluasi<textarea name="indicator" required minlength="10" maxlength="1500">${esc(r.indicator)}</textarea></label><p class="error" role="alert"></p><button class="btn" type="submit">Simpan rencana tindakan</button></form><p class="login-note">Disimpan sebagai usulan dengan snapshot bukti. Penetapan kebijakan tetap melalui peninjauan manusia.</p>`);}
  function planModal(id){if(role()!=='staff')return;const p=state().actionPlans.find(p=>p.id===id);if(!p)return;modal('Rencana & hasil evaluasi',`<h3>${esc(p.title)}</h3><details open class="evidence-snapshot"><summary>Dasar rekomendasi saat rencana dibuat</summary><p>${esc(p.evidence.finding)}</p><p>${esc(p.evidence.evidence)}</p><small>${esc(p.evidence.source)} · ${fmt(p.evidence.updatedAt)}<br>Cakupan: ${esc(Object.values(p.scope).filter(Boolean).join(' / ')||'Semua')}</small><p>${esc(p.evidence.limit)}</p></details><p>${esc(p.proposal)}</p><p><strong>Indikator:</strong> ${esc(p.indicator)}</p><form id="plan-evaluation-form" data-id="${id}"><label class="field">Penanggung jawab<select name="owner">${['Alya Rahma','Bima Prasetyo'].map(n=>`<option ${n===p.owner?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Waktu evaluasi<input type="date" name="reviewDate" required value="${esc(p.reviewDate)}"></label><label class="field">Status rencana<select name="status">${['Usulan','Disetujui','Berjalan','Dievaluasi','Ditutup'].map(n=>`<option ${n===p.status?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Hasil evaluasi dan kebutuhan tindak lanjut<textarea name="result" aria-label="Hasil evaluasi dan kebutuhan tindak lanjut" maxlength="2500">${esc(p.result)}</textarea><small>Wajib diisi sebelum Dievaluasi atau Ditutup. Perubahan angka tidak otomatis membuktikan dampak program.</small></label><p class="error" role="alert"></p><button class="btn" type="submit">Simpan evaluasi</button></form>`);}

  document.addEventListener('click',e=>{
    const target=e.target.closest('[data-metric],[data-eval-tab],[data-chat-question],[data-recommendation],[data-plan],[data-action="faq-open"],[data-action="chat-handoff"]');if(!target)return;e.stopImmediatePropagation();
    try{
      if(target.dataset.action==='faq-open'){openChat();return;}
      if(target.dataset.action==='chat-handoff'){handoff();return;}
      if(target.dataset.chatQuestion!==undefined){ask(CHAT_SUGGESTIONS[Number(target.dataset.chatQuestion)]);return;}
      if(role()!=='staff'){toast('Buka demo petugas untuk tindakan ini.');return;}
      if(target.dataset.metric!==undefined){api.getFilters().metric=target.dataset.metric;api.getFilters().status='';closeModal();go('followup');return;}
      if(target.dataset.evalTab){api.setEvalTab(target.dataset.evalTab);render();return;}
      if(target.dataset.recommendation){recommendationModal(target.dataset.recommendation);return;}
      if(target.dataset.plan){planModal(target.dataset.plan);return;}
    }catch(err){toast(err.message);}
  });
  document.addEventListener('submit',async e=>{
    const form=e.target;const supported=['chat-form','workflow-ticket-form','action-plan-form','plan-evaluation-form','followup-note-form'].includes(form.id)||form.matches('.requirement-upload,.document-review');if(!supported)return;e.preventDefault();e.stopImmediatePropagation();const fd=new FormData(form);const button=form.querySelector('[type="submit"]');const buttonLabel=button?.innerHTML;
    try{
      if(form.id==='chat-form'){ask(fd.get('question'));return;}
      if(form.id==='workflow-ticket-form'){if(role()!=='student')throw Error('Tindakan hanya untuk demo calon mahasiswa.');const t=createTicket(state(),{category:fd.get('category'),text:fd.get('text'),conversation:conversationDraft});conversationDraft='';persist();closeModal();go('help');toast('Tiket '+t.id+' dibuat dan penanggung jawab dicatat.');return;}
      if(form.matches('.requirement-upload')){
        if(role()!=='student')throw Error('Tindakan hanya untuk demo calon mahasiswa.');const f=fd.get('document');if(!f?.size||f.size>5*1024*1024||!/\.(pdf|png|jpe?g)$/i.test(f.name))throw Error('Pilih PDF, JPG, atau PNG berukuran maksimum 5 MB.');
        button.disabled=true;button.textContent='Memeriksa berkas…';const bytes=new Uint8Array(await f.slice(0,8).arrayBuffer());const valid=/\.pdf$/i.test(f.name)?bytes[0]===0x25&&bytes[1]===0x50&&bytes[2]===0x44&&bytes[3]===0x46:/\.png$/i.test(f.name)?bytes[0]===0x89&&bytes[1]===0x50&&bytes[2]===0x4e&&bytes[3]===0x47:bytes[0]===0xff&&bytes[1]===0xd8;if(!valid)throw Error('Isi berkas tidak sesuai format. Gunakan PDF atau gambar yang valid.');
        submitRequirement(state(),DEMO_CANDIDATE,form.dataset.requirement,{name:f.name,size:f.size,type:f.type});persist();render();toast('Dokumen diterima dan menunggu pemeriksaan petugas.');return;
      }
      if(role()!=='staff')throw Error('Tindakan memerlukan petugas.');
      if(form.matches('.document-review')){reviewRequirement(state(),form.dataset.caseId,form.dataset.requirement,fd.get('decision'),fd.get('reason'),fd.get('reasonCode'));persist();render();caseModal(form.dataset.caseId);toast('Hasil pemeriksaan diperbarui pada pendaftaran calon mahasiswa.');return;}
      if(form.id==='followup-note-form'){const c=state().cases.find(c=>c.id===form.dataset.id);c.lastFollowup=state().now;audit(state(),'Petugas',c.id,'Catatan tindak lanjut','',fd.get('note').trim());persist();render();caseModal(c.id);toast('Tindak lanjut dicatat.');return;}
      if(form.id==='action-plan-form'){const r=recommendations(state(),api.getFilters()).find(r=>r.id===form.dataset.id);saveActionPlan(state(),r,Object.fromEntries(fd.entries()));persist();closeModal();api.setEvalTab('plans');go('evaluation');toast('Rencana disimpan bersama dasar rekomendasinya.');return;}
      if(form.id==='plan-evaluation-form'){updateActionPlan(state(),form.dataset.id,Object.fromEntries(fd.entries()));persist();closeModal();render();toast('Hasil evaluasi tersimpan.');return;}
    }catch(err){const error=form.querySelector('.error');if(error)error.textContent=err.message;else toast(err.message);}finally{if(button?.isConnected){button.disabled=false;button.innerHTML=buttonLabel;}}
  });
  return {openChat,newTicket,ticketModal,caseModal};
}
